use vstd::prelude::*;

verus! {

spec fn has_odd(v: Seq<u64>) -> bool {
    exists|i: int| 0 <= i < v.len() && v[i] % 2 == 1
}

fn choose_odd(v: &Vec<u64>) -> (idx: usize)
    requires
        has_odd(v@),
    ensures
        idx < v.len(),
        v@[idx as int] % 2 == 1,
{
    for (i, &x) in v.iter().enumerate()
        invariant
            i <= v.len(),
            // no odd element has appeared in the already-scanned prefix
            forall|j: int| 0 <= j < i ==> v@[j] % 2 != 1,
            // because an odd exists somewhere in the whole vector, one exists
            // at or after the current index
            exists|k: int| i <= k < v.len() && v@[k] % 2 == 1,
        decreases
            v.len() - i
    {
        if x % 2 == 1 {
            // connect iterator element `x` to the spec sequence value at `i`
            assert(x == v@[i as int]);
            return i;
        } else {
            // establish the "no odd in prefix" fact for the next iteration
            assert(x == v@[i as int]);
            assert(v@[i as int] % 2 != 1);
        }
    }
    // Problem statement guarantees at least one odd element.
    unreachable!("input vector must contain at least one odd element")
}

} // verus!